import type {GetVersionApiResponse} from '../../../../services/rest'
import {restBaseApi} from '../../../../services/restBase'

export const editFederationApi = restBaseApi.injectEndpoints({
  endpoints: build => ({
    testConnection: build.query<GetVersionApiResponse, string>({
      query: url => ({
        url: `${url}/app/rest/version`,
        responseHandler: 'text',
      }),
    }),
  }),
})
