import type {KeyValue} from '@jetbrains/teamcity-ui/dist/utils'
import {useMemo} from 'react'
import {graphql, useFragment} from 'react-relay'

import {
  getBuildTypesHash,
  getOverviewData,
  getOverviewProjectsHash,
  getProjectsHash,
  getProjectTemplates,
  getHasProjects,
  getAllProjectsReady,
  getPipelinesHash,
} from '../selectors'
import type {TreeFilter, ProjectsTree} from '../selectors/projectTrees'
import {
  getProjectsAndOverviewReady,
  createSearchProjectsTree,
  getAllProjectsTitleItem,
  getAllProjectsTreeData,
  getFederationServersData,
  getHasFavoriteProjects,
  getMergedProjectsData,
  getOverviewTreeData,
  getSearchProjectsExpandState,
  mergeProjectsForSidebar,
  mergeSearchProjectsTree,
  upgradeSearchProjectsTreeByExpandState,
} from '../selectors/projectTrees'
import type {FederationServerId, ProjectId, Template} from '../types'
import {ROOT_PROJECT_ID} from '../types'
import {currentServerId} from '../types/projectTrees'
import {convertDataToTree} from '../utils/convertDataToTree'
import {emptyArray, getEmptyHash} from '../utils/empty'
import type {WritableMap} from '../utils/object'

import type {projectTreesFederationServersFragment$key} from './__generated__/projectTreesFederationServersFragment.graphql'
import {useAppSelector} from './react-redux'

const federationServersFragment = graphql`
  fragment projectTreesFederationServersFragment on FederationServers {
    server {
      url
    }
  }
`

export function useFederationServers(
  key: projectTreesFederationServersFragment$key | null,
): ReadonlyArray<string> {
  const {server} = useFragment(federationServersFragment, key) ?? {}
  return useMemo(() => server?.map(({url}) => url ?? '') ?? emptyArray, [server])
}

export function useDefaultSearchProjectsTree(
  federationServersKey: projectTreesFederationServersFragment$key | null,
  filter: TreeFilter = Object.freeze({}),
  showArchived?: boolean,
) {
  const ready = useAppSelector(state => getProjectsAndOverviewReady(state, filter.parentId))
  const allProjectsReady = useAppSelector(state => getAllProjectsReady(state))
  const projectsReady =
    !filter.parentId || filter.parentId === ROOT_PROJECT_ID ? allProjectsReady : ready
  const mergedProjectsSelector = useMemo(() => getMergedProjectsData(), [])
  const data = useAppSelector(state => mergedProjectsSelector(state, filter.parentId))
  const buildTypes = useAppSelector(getBuildTypesHash)
  const pipelines = useAppSelector(getPipelinesHash)
  const projects = useAppSelector(getProjectsHash)
  const templates: KeyValue<ProjectId, ReadonlyArray<Template>> = useAppSelector(state =>
    filter.includeTemplates ? getProjectTemplates(state) : getEmptyHash(),
  )
  const federationServers = useFederationServers(federationServersKey)
  const federationServersData = useAppSelector(getFederationServersData)
  const showArchivedProjects = useAppSelector(
    state => showArchived ?? state.projectsSidebar.showArchivedProjects,
  )
  const filteredData = useMemo(
    () => (showArchivedProjects ? data : data.filter(id => !projects[id]?.archived)),
    [data, projects, showArchivedProjects],
  )
  return useMemo(() => {
    const result: WritableMap<FederationServerId, ProjectsTree | null | undefined> = new Map()
    const currentServerTree = convertDataToTree({
      ready: projectsReady,
      data: filteredData,
      buildTypes,
      pipelines,
      projects,
      templates,
      group: 'search',
      filter,
      showArchivedProjects,
    })

    if (currentServerTree) {
      result.set(currentServerId, currentServerTree)
    }

    federationServers.forEach(serverId => {
      const serverData = federationServersData[serverId]
      const serverEntities = serverData?.projects?.entities

      if (
        serverData?.projects &&
        serverEntities?.pipelines &&
        serverEntities?.buildTypes &&
        serverEntities.projects
      ) {
        const serverTree = convertDataToTree({
          ready: projectsReady,
          data: serverData.projects.result,
          buildTypes: serverEntities.buildTypes,
          pipelines: serverEntities.pipelines,
          projects: serverEntities.projects,
          group: 'search',
          serverId,
          showArchivedProjects,
        })

        if (serverTree) {
          result.set(serverId, serverTree)
        }
      }
    })

    return result
  }, [
    projectsReady,
    filteredData,
    buildTypes,
    pipelines,
    projects,
    templates,
    filter,
    showArchivedProjects,
    federationServers,
    federationServersData,
  ])
}

export function useHasArchivedDescendants(filter: TreeFilter | undefined) {
  const treeByServer = useDefaultSearchProjectsTree(null, filter, true)
  return treeByServer.get(currentServerId)?.data.some(item => item.archived) ?? false
}

function useSearchProjectsTreeDefault(
  federationServersKey: projectTreesFederationServersFragment$key | null,
) {
  const searchQuery = useAppSelector(state => state.projectsSidebar.searchQuery)
  const defaultTreeByServer = useDefaultSearchProjectsTree(federationServersKey)
  const togglingOverview = useAppSelector(state => state.togglingOverview)
  const overviewData = useAppSelector(getOverviewData)
  const overviewProjectsHash = useAppSelector(getOverviewProjectsHash)
  const federationServers = useFederationServers(federationServersKey)
  return useMemo(
    () =>
      createSearchProjectsTree({
        searchQuery,
        defaultTreeByServer,
        togglingOverview,
        overviewData,
        overviewProjectsHash,
        federationServers,
      }),
    [
      defaultTreeByServer,
      federationServers,
      overviewData,
      overviewProjectsHash,
      searchQuery,
      togglingOverview,
    ],
  )
}

function useSearchProjectsTree(
  federationServersKey: projectTreesFederationServersFragment$key | null,
) {
  const federationServers = useFederationServers(federationServersKey)
  const searchProjectsTree = useSearchProjectsTreeDefault(federationServersKey)
  const expandStates = useAppSelector(getSearchProjectsExpandState)
  return useMemo(
    () =>
      upgradeSearchProjectsTreeByExpandState(federationServers, searchProjectsTree, expandStates),
    [expandStates, federationServers, searchProjectsTree],
  )
}

export function useSearchProjectsTreeMerged(
  federationServersKey: projectTreesFederationServersFragment$key | null,
) {
  const treeByServer = useSearchProjectsTree(federationServersKey)
  const federationServers = useFederationServers(federationServersKey)
  const federationServersData = useAppSelector(getFederationServersData)
  return useMemo(
    () => mergeSearchProjectsTree(treeByServer, federationServers, federationServersData),
    [federationServers, federationServersData, treeByServer],
  )
}

export function useProjectsForSidebar() {
  const isFavoriteItemOpen = useAppSelector(
    state => state.projectsSidebar.activeItem?.isFavoriteItemOpen,
  )
  const favoriteProjects = useAppSelector(getOverviewTreeData)
  const hasFavoriteProjects = useAppSelector(getHasFavoriteProjects)
  const allProjects = useAppSelector(getAllProjectsTreeData)
  const allProjectsTitleItem = useAppSelector(getAllProjectsTitleItem)
  const canShowProjectsToggle = useAppSelector(getHasProjects)

  return useMemo(
    () =>
      mergeProjectsForSidebar(
        favoriteProjects,
        hasFavoriteProjects,
        allProjects,
        allProjectsTitleItem,
        true,
        canShowProjectsToggle,
        isFavoriteItemOpen,
      ),
    [
      allProjects,
      allProjectsTitleItem,
      canShowProjectsToggle,
      favoriteProjects,
      hasFavoriteProjects,
      isFavoriteItemOpen,
    ],
  )
}
