import Button from '@jetbrains/ring-ui-built/components/button/button'
import Input from '@jetbrains/ring-ui-built/components/input/input'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {baseUri} from '@jetbrains/teamcity-ui'
import {IconButton, SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {QueryStatus} from '@reduxjs/toolkit/query'
import classNames from 'classnames'
import * as React from 'react'
import {useEffect} from 'react'
import {arrayMove, List} from 'react-movable'
import type {EntryPointProps} from 'react-relay'
import {graphql, useMutation, usePreloadedQuery} from 'react-relay'
import type {RecordSourceSelectorProxy} from 'relay-runtime/lib/store/RelayStoreTypes'
import shallowEqual from 'shallowequal'

import {useFederationServers} from '../../../../hooks/projectTrees'
import {useObjectSlice} from '../../../../hooks/useSlice'
import type {FederationServerId} from '../../../../types'
import {stringifyId} from '../../../../types'
import {resolveHelpURL} from '../../../../utils/url'
import HelpLink from '../../../common/HelpLink/HelpLink'

import type {
  EditFederationMutation,
  EditFederationMutation$data,
} from './__generated__/EditFederationMutation.graphql'
import type {EditFederationQuery} from './__generated__/EditFederationQuery.graphql'
import {query} from './EditFederation.queries'
import {editFederationApi} from './EditFederation.rest'

import styles from './EditFederation.module.css'

type ServerProps = React.JSX.IntrinsicElements['li'] & {
  url: FederationServerId
  onRemove: (id: FederationServerId) => unknown
  isDragged: boolean
}
const Server = React.forwardRef(function Server(
  {url, onRemove, isDragged, ...restProps}: ServerProps,
  ref: React.Ref<HTMLLIElement>,
) {
  const handleRemove = React.useCallback(() => onRemove(url), [onRemove, url])
  const {status, refetch} = editFederationApi.endpoints.testConnection.useQuery(url, {
    selectFromResult: ({status}) => ({status}),
  })
  return (
    <li
      {...restProps}
      ref={ref}
      className={classNames(styles.item, {
        [styles.dragged]: isDragged,
      })}
    >
      <SvgIcon icon="drag" className={styles.handle} />
      <span className={styles.url}>{stringifyId(url)}</span>
      {status === QueryStatus.fulfilled && (
        <span className={styles.success}>{'Successful connection'}</span>
      )}
      {status === QueryStatus.rejected && (
        <span
          className={styles.error}
          title={`HTTP request failed. Check that you are logged in and CORS on target server is enabled for ${baseUri}`}
        >
          {'HTTP request failed. Check that you are '}
          <Link href={stringifyId(url)} target="_blank" rel="noreferrer">
            {'logged in'}
          </Link>
          {' and '}
          <HelpLink preservePlus url={resolveHelpURL('rest-api.html#CORS-support')}>
            {'CORS'}
          </HelpLink>
          {' on target server is enabled for '}
          {baseUri}
        </span>
      )}
      <Button onClick={refetch}>{'Test connection'}</Button>
      <IconButton title="Remove server" icon="close" onClick={handleRemove} />
    </li>
  )
})

const cleanUrl = (url: string) => url.trim().replace(/\/$/, '')

type State = {
  server: string
  servers: readonly string[]
}
type PayloadMap = {
  setServer: string
  setServers: readonly string[]
  add: void
  remove: string
  move: {
    oldIndex: number
    newIndex: number
  }
}

const mutation = graphql`
  mutation EditFederationMutation($input: FederationServersInput!) @raw_response_type {
    replaceFederationServers(input: $input) {
      server {
        url
      }
    }
  }
`

export default function EditFederation({queries}: EntryPointProps<Queries, {}, {}, {}>) {
  const {federationServers = null} = usePreloadedQuery(query, queries.main)
  const savedServers = useFederationServers(federationServers)
  const [{server, servers}, {setServer, setServers, add, remove, move}] = useObjectSlice<
    State,
    PayloadMap
  >(
    {
      setServer: (_, value) => ({
        server: value,
      }),
      setServers: (_, servers) => ({
        servers,
      }),
      add: state => ({
        server: '',
        servers: state.servers.concat(cleanUrl(state.server)),
      }),
      remove: (state, serverToDelete) =>
        state.servers.includes(serverToDelete)
          ? {
              servers: state.servers.filter(item => item !== serverToDelete),
            }
          : null,
      move: (state, {oldIndex, newIndex}) => ({
        servers: arrayMove([...state.servers], oldIndex, newIndex),
      }),
    },
    {
      server: '',
      servers: savedServers,
    },
  )
  useEffect(() => {
    setServers(savedServers)
  }, [savedServers, setServers])

  const [editFederationServers] = useMutation<EditFederationMutation>(mutation)
  const updater = (store: RecordSourceSelectorProxy<EditFederationMutation$data>) => {
    const response = store.getRootField('replaceFederationServers')
    store.getRoot().setLinkedRecord(response, 'federationServers')
  }

  const input = {
    server: servers.map(url => ({
      url,
    })),
  }

  const save = () =>
    editFederationServers({
      variables: {
        input,
      },
      optimisticResponse: {replaceFederationServers: input},
      optimisticUpdater: updater,
      updater,
    })

  const isChanged = !shallowEqual(servers, savedServers)
  const url = cleanUrl(server)
  return (
    <>
      <form
        className={styles.form}
        onSubmit={e => {
          e.preventDefault()
          add()
        }}
      >
        <Input
          className={styles.input}
          placeholder="TeamCity server URL"
          value={server}
          onChange={e => setServer(e.currentTarget.value)}
        />
        <Button
          className={styles.add}
          type="submit"
          disabled={url.length === 0 || servers.includes(url)}
        >
          {'Add server'}
        </Button>
      </form>
      {servers.length > 0 ? (
        <List
          values={[...servers]}
          onChange={move}
          renderList={({children, props}) => (
            <ul className={styles.list} {...props}>
              {children}
            </ul>
          )}
          renderItem={({value, props, isDragged, isSelected}) => (
            <Server
              {...props}
              key={stringifyId(value)}
              isDragged={isDragged || isSelected}
              url={value}
              onRemove={remove}
            />
          )}
        />
      ) : (
        <div className={styles.note}>{'No attached servers'}</div>
      )}
      <div className={styles.saveContainer}>
        <Button onClick={save} className={styles.save} primary disabled={!isChanged}>
          {'Save changes'}
        </Button>
      </div>
      {isChanged && (
        <div
          className="modifiedMessage"
          style={{
            display: 'block',
          }}
        >
          <div className="messageBody">
            {'The changes are not yet saved. '}
            <Button onClick={save}>{'Save'}</Button>
          </div>
        </div>
      )}
    </>
  )
}

type Queries = {main: EditFederationQuery}

export type EditFederationComponent = typeof EditFederation
